u=symbols('u1:5'); a,b,c,d,e=symbols('a b c d e'); from sympy.utilities.iterables import multiset_permutations; F=0
for pat,co in [((4,0,0,0),a),((3,1,0,0),b),((2,2,0,0),c),((2,1,1,0),d),((1,1,1,1),e)]:
  for p in multiset_permutations(list(pat)): F+=co*factorial(4)/prod([factorial(k) for k in p])*prod([u[i]**p[i] for i in range(4)])
DF=expand(sum(diff(F,v) for v in u)); [DF.coeff(u[0],3).subs({u[1]:0,u[2]:0,u[3]:0}), DF.coeff(u[0],2).coeff(u[1],1).subs({u[2]:0,u[3]:0})]
